;(()=>{
  const markIdentity=()=>{
    const ids=[...document.querySelectorAll("body *")].filter(el=>{
      if(el.children.length!==0)return false;
      const t=(el.textContent||"").trim();
      return /^YON-\d{4,}\s*·\s*Yönetici$/i.test(t);
    });

    for(const id of ids){
      const parent=id.parentElement;
      if(!parent)continue;
      const children=[...parent.children];
      if(children.length<2 || children.length>4)continue;

      const first=(children[0]?.textContent||"").trim();
      const all=(parent.textContent||"").trim();

      if(first && all.length<100){
        document.querySelectorAll(".pire-header-user-identity")
          .forEach(el=>el.classList.remove("pire-header-user-identity"));
        parent.classList.add("pire-header-user-identity");
        break;
      }
    }
  };

  if(document.readyState==="loading"){
    document.addEventListener("DOMContentLoaded",markIdentity);
  }else{
    markIdentity();
  }

  let scheduled=false;
  new MutationObserver(()=>{
    if(scheduled)return;
    scheduled=true;
    requestAnimationFrame(()=>{
      scheduled=false;
      markIdentity();
    });
  }).observe(document.body,{childList:true,subtree:true});
})();

